  Missing test coverage: remote wins with non-empty local version history.

  This test and the "local wins" test below both use empty versions arrays
  for both parties. The WR-08 test only covers the local-wins case. There's
  no test verifying that when remote wins, the loser's (local's) non-empty
  version history is preserved in the merge.

  Adding such a test would have caught the bug in line 346 where
  remoteMeta.versions is passed instead of loser.versions, causing local
  version history loss when remote wins.






  💡 Suggested test case

  it('preserves local version history when remote wins conflict', async () => {
    const localVersions: VersionEntry[] = [makeVersion('local-v1', 5000), makeVersion('local-v2', 4000)];
    const localCurrent = { ...baseCurrentMetadata, cid: 'local-cid', modifiedAt: 3000, versions: localVersions };
    const remoteMeta = {
      ...baseCurrentMetadata,
      cid: 'remote-cid',
      modifiedAt: 9000, // remote wins
      versions: [makeVersion('remote-v1', 6000)] as VersionEntry[],
    };

    vi.mocked(resolveIpnsRecord)
      .mockResolvedValueOnce({ cid: 'old-meta', sequenceNumber: 5n, signatureVerified: true })
      .mockResolvedValueOnce({ cid: 'remote-meta-cid', sequenceNumber: 6n, signatureVerified: true });

    const conflict409 = Object.assign(new Error('Conflict'), { status: 409 });
    vi.mocked(createAndPublishIpnsRecord)
      .mockRejectedValueOnce(conflict409)
      .mockResolvedValueOnce({ success: true, sequenceNumber: 7n });

    vi.mocked(fetchFromIpfs).mockResolvedValue(
      new TextEncoder().encode(JSON.stringify({ iv: 'r-iv', data: 'r-data' }))
    );
    decryptFileMetadata.mockResolvedValue(remoteMeta as any);

    await updateFileMetadata({
      fileIpnsPrivateKey: mockPrivateKey,
      fileMetaIpnsName: 'k51-file-ipns',
      folderKey: mockFolderKey,
      currentMetadata: localCurrent,
      updates: { cid: 'local-cid', size: localCurrent.size },
      createVersion: false,
      ctx: mockCtx,
    });

    // Verify local's version history is preserved in the merge
    const retryPayload = encryptFileMetadata.mock.calls[1][0];
    const retryVersionCids = (retryPayload.versions ?? []).map((v: VersionEntry) => v.cid);
    expect(retryVersionCids).toContain('local-v1');
    expect(retryVersionCids).toContain('local-v2');
  });


